// Retire le préfixe de statut du nom de dossier pour obtenir le titre produit.
const dossier = $input.first().json;
const folderName = String(dossier.name || '');
const titre = folderName.replace(/^\s*(✓_|✅_|⚠_|\$_|\*)\s*/, '').trim();

return [{ json: { folderId: dossier.id, folderName, titre } }];

// Ne garde que les images, et les trie par numéro : 1.webp, 2.webp, ... 10.webp.
// L'ordre compte : la première image devient l'image principale de la fiche Shopify.
return $input.all()
  .filter((i) => typeof i.json.mimeType === 'string' && i.json.mimeType.startsWith('image/'))
  .sort((a, b) => String(a.json.name).localeCompare(String(b.json.name), 'fr', { numeric: true }));

const originalBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const originalBase64 = originalBuffer.toString('base64');
const mimeType = $input.first().binary.data.mimeType || 'image/jpeg';

return [{ json: { originalBase64, mimeType }, binary: $input.first().binary }];

const compressedBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64Compressed = compressedBuffer.toString('base64');

const base64Data = $json.originalBase64;
const mimeType = $json.mimeType;
const mimeTypeCompressed = $input.first().binary.data.mimeType || mimeType;
const nom = $('Télécharger binaire (pour IA)').first().json.name || '';

return [{ json: { base64Data, base64Compressed, mimeTypeCompressed, mimeType, nom } }];

const allItems = $json.photos;

const imageParts = allItems.map(item => ({
  inline_data: {
    mime_type: 'image/jpeg',
    data: item.base64Compressed
  }
}));

const titre = $('Nettoyer titre produit').first().json.titre;

const promptText = `Tu es une copywriter experte pour une boutique de vêtements vintage/seconde main en ligne, au ton complice, girly et inspirant, avec des emojis.

Analyse les photos fournies de ce vêtement (nom de dossier : "${titre}").

Réponds UNIQUEMENT avec un objet JSON valide (aucun texte autour, aucune balise markdown, aucun \`\`\`), avec exactement ces clés :
{
  "emoji": "un seul emoji qui représente bien la pièce (type de vêtement, couleur ou motif dominant), à utiliser en préfixe du titre produit",
  "mood": "un paragraphe d'intro avec 1-2 emojis, ton décontracté et engageant, qui présente la pièce, sa coupe et ses détails distinctifs visibles sur les photos (poches, col, boutons, matière, motif...). NE PAS inclure de label du type 'Le mood :' au début, juste le texte direct.",
  "conseils_style": "1-2 phrases de conseils de stylisme concrets pour porter la pièce",
  "marque": "nom de la marque si visible sur une étiquette dans les photos, sinon 'Non précisée'",
  "etat": "estimation de l'état du vêtement basé sur les photos, format 'Très bon état 9/10' ou équivalent",
  "composition": "composition matière si visible sur étiquette, sinon estimation raisonnable basée sur l'aspect visuel",
  "taille": "taille si visible sur étiquette, avec commentaire sur la coupe si pertinent (ajustée/oversize/etc.)",
  "product_type": "catégorie du produit (ex: Chemise, Robe, Pantalon, T-shirt...)",
  "tags": ["5 à 8 tags pertinents en minuscules pour le SEO et le filtrage boutique (style, couleur, matière, type de pièce)"]
}`;

const body = {
  contents: [
    {
      parts: [
        { text: promptText },
        ...imageParts
      ]
    }
  ],
  generationConfig: {
    temperature: 0.7,
    response_mime_type: 'application/json'
  }
};

return [{ json: { body, titre } }];

const response = $input.first().json;

if (response.error) {
  return [{ json: { skip: true, raison: JSON.stringify(response.error) } }];
}

const rawText = response.candidates[0].content.parts[0].text;

let fiche;
try {
  fiche = JSON.parse(rawText);
} catch (e) {
  throw new Error('Réponse Gemini non-JSON : ' + rawText);
}

const titre = $('Préparer requête Gemini').first().json.titre;
const titreAvecEmoji = `${fiche.emoji} ${titre}`.trim();

const body_html =
  `<p><strong>Le mood :</strong> ${fiche.mood}</p>` +
  `<p><strong>✨ Nos conseils de style :</strong><br>${fiche.conseils_style}</p>` +
  `<p><strong>🔍 Les détails de la pépite :</strong></p>` +
  `<p>- <strong>Marque :</strong> ${fiche.marque} 🏷️<br>` +
  `- <strong>État :</strong> ${fiche.etat} ✨<br>` +
  `- <strong>Composition :</strong> ${fiche.composition}<br>` +
  `- <strong>Taille indiquée / estimée :</strong> ${fiche.taille}</p>` +
  `<p><strong>📸 Info Mannequin & Fit :</strong><br>Pour t'aider à visualiser : notre mannequin fait une taille 36. Attention, ne te fie pas forcément au tombé sur les photos ! Il nous arrive très souvent de lui faire porter des pièces plus grandes et de les styliser (épinglées, nouées, ceinturées...) pour te donner un max d'inspiration sur la façon de les porter. Pense à bien checker les tailles indiquées ! 📏</p>` +
  `<p><strong>♻️ À propos de notre sélection :</strong><br>Chaque vêtement de la boutique est une pièce de seconde main, chinée et triée à la main avec énormément d'amour. Même si on vérifie tout avec soin, il s'agit de vêtements qui ont déjà vécu leur best life : de minuscules traces d'usure ou une petite marge d'erreur dans les mesures sont toujours possibles. C'est aussi ça la magie du vintage ! 🫶🌍</p>`;

// Pas d'images ici : elles seront uploadées une par une après la création du produit
const payload = {
  product: {
    title: titreAvecEmoji,
    body_html,
    vendor: fiche.marque,
    product_type: fiche.product_type,
    tags: fiche.tags.join(', '),
    status: 'draft',
    variants: [
      {
        inventory_management: 'shopify',
        inventory_policy: 'deny',
        inventory_quantity: 1
      }
    ]
  }
};

return [{ json: payload }];

const response = $input.first().json;
const productId = response.product.id;

const allPhotos = $('Agréger toutes les photos').first().json.photos;

// L'ordre est celui du dossier (1, 2, 3...) : la première image devient l'image principale.
const EXT = { 'image/webp': 'webp', 'image/png': 'png', 'image/jpeg': 'jpg', 'image/gif': 'gif' };

return allPhotos.map((item, idx) => {
  const ext = EXT[item.mimeType] || String(item.nom || '').split('.').pop() || 'jpg';
  return {
    json: {
      productId,
      base64Data: item.base64Data,
      filename: `photo-${idx + 1}.${ext}`,
      position: idx + 1,
    },
  };
});
